constexpr UINT completeMessage=WM_APP+1;
constexpr COLORREF background=RGB(15,15,15),surface=RGB(43,43,43),border=RGB(86,86,86),textColor=RGB(246,246,246),secondary=RGB(186,186,186);
const wchar_t* sections[]={L"Dashboard",L"Audio Mixer",L"Virtual Devices",L"Voice Effects",L"Soundboard",L"Application Audio",L"Recorder",L"Broadcasting",L"Settings"};
const wchar_t* sources[]={L"Microphone",L"Input 2",L"Input 3",L"Input 4",L"Soundboard",L"Application audio"};
